/* config.h for the subset of GSL 2.7.1 built with Neper.
 *
 * This file replaces the config.h generated by GSL's configure script.  It
 * only defines what the bundled sources need, and assumes a C99 compiler
 * and a C99 math library. */

/* Use inline functions (C99 semantics) */
#define HAVE_INLINE 1
#define HAVE_C99_INLINE 1

/* C99 math functions and macros */
#define HAVE_DECL_ACOSH 1
#define HAVE_DECL_ASINH 1
#define HAVE_DECL_ATANH 1
#define HAVE_DECL_EXPM1 1
#define HAVE_DECL_FREXP 1
#define HAVE_DECL_HYPOT 1
#define HAVE_DECL_LDEXP 1
#define HAVE_DECL_LOG1P 1
#define HAVE_DECL_ISFINITE 1
#define HAVE_DECL_ISINF 1
#define HAVE_DECL_ISNAN 1
#define HAVE_DECL_FINITE 0
#define HAVE_IEEE_COMPARISONS 1
#define HAVE_IEEE_DENORMALS 1

/* x87 floating-point unit (32-bit x86 without SSE2 math) */
#if (defined(__i386__) || defined(_M_IX86)) && !defined(__SSE2_MATH__)
#define HAVE_EXTENDED_PRECISION_REGISTERS 1
#else
#define HAVE_EXTENDED_PRECISION_REGISTERS 0
#endif

#define PACKAGE_VERSION "2.7.1"
#define VERSION "2.7.1"

/* The remainder is taken verbatim from GSL's config.h.in */

#if HAVE_EXTENDED_PRECISION_REGISTERS
#define GSL_COERCE_DBL(x) (gsl_coerce_double(x))
#else
#define GSL_COERCE_DBL(x) (x)
#endif

#ifdef __GNUC__
#define DISCARD_POINTER(p) do { ; } while(p ? 0 : 0);
#else
#define DISCARD_POINTER(p) /* ignoring discarded pointer */
#endif

#if defined(GSL_RANGE_CHECK_OFF) || !defined(GSL_RANGE_CHECK)
#define GSL_RANGE_CHECK 0  /* turn off range checking by default internally */
#endif

#define RETURN_IF_NULL(x) if (!x) { return ; }
